sp_widget.client_script:
api.controller = function() {

    var c = this;


    /*
     * =========================================
     * INITIALIZE
     * =========================================
     */

    c.loading = false;


    /*
     * =========================================
     * REFRESH REGISTRATIONS
     * =========================================
     *
     * Can be called later if we add
     * refresh functionality.
     */

    c.refreshRegistrations = function() {

        c.loading = true;


        c.server.update().then(
            function(response) {

                c.data =
                    response.data;

                c.loading = false;

            },
            function(error) {

                console.log(
                    'My Registrations error:',
                    error
                );

                c.loading = false;

            }
        );

    };

};

sp_widget.css:
/* =========================================
   CAMPUS CONNECT - MY REGISTRATIONS
   ========================================= */

.cc-my-registrations {

    width: 110%;

    max-width: none;

    margin: 0;

    padding: 28px 30px 50px 200px;

    box-sizing: border-box;

    color: #14213d;

    font-family: inherit;

}


/* =========================================
   PAGE HEADER
   ========================================= */

.cc-page-header {

    margin-bottom: 22px;

}


.cc-eyebrow {

    margin-bottom: 6px;

    color: #0066ff;

    font-size: 11px;

    font-weight: 700;

    letter-spacing: 1.3px;

    line-height: 1.2;

}


.cc-page-header h1 {

    margin: 0 0 6px;

    color: #07152f;

    font-size: 28px;

    font-weight: 700;

    line-height: 1.2;

    letter-spacing: -.2px;

}


.cc-page-header p {

    margin: 0;

    color: #52627a;

    font-size: 13px;

    line-height: 1.5;

}


/* =========================================
   REGISTRATION TABLE
   ========================================= */

.cc-registration-panel {

    width: 100%;

    overflow: hidden;

    border: 1px solid #cfd9e6;

    border-radius: 6px;

    background: #ffffff;

    box-shadow:
        0 3px 10px rgba(
            7,
            21,
            47,
            .05
        );

}


/* =========================================
   TABLE HEADER
   ========================================= */

.cc-table-header {

    display: grid;

    grid-template-columns:
        2.05fr
        1.45fr
        1.45fr
        1.3fr
        .85fr
        .7fr;

    align-items: center;

    min-height: 34px;

    padding: 0 17px;

    box-sizing: border-box;

    background: #f0f4f9;

    border-bottom: 1px solid #d8e0ea;

    color: #52627a;

    font-size: 9px;

    font-weight: 700;

    letter-spacing: .45px;

}


.cc-table-header span {

    white-space: nowrap;

}


/* =========================================
   TABLE ROW
   ========================================= */

.cc-registration-row {

    display: grid;

    grid-template-columns:
        2.05fr
        1.45fr
        1.45fr
        1.3fr
        .85fr
        .7fr;

    align-items: center;

    min-height: 54px;

    padding: 0 17px;

    box-sizing: border-box;

    border-bottom: 1px solid #dce4ed;

    color: #34445c;

    font-size: 11px;

    background: #ffffff;

    transition:
        background .15s ease;

}


.cc-registration-row:last-child {

    border-bottom: none;

}


.cc-registration-row:hover {

    background: #fafcff;

}


/* =========================================
   EVENT NAME
   ========================================= */

.cc-event-name {

    overflow: hidden;

    padding-right: 15px;

    color: #07152f;

    font-size: 11px;

    font-weight: 700;

    line-height: 1.3;

    text-overflow: ellipsis;

    white-space: nowrap;

}


/* =========================================
   REGISTRATION ID
   ========================================= */

.cc-registration-id {

    overflow: hidden;

    color: #40516a;

    font-size: 11px;

    line-height: 1.3;

    text-overflow: ellipsis;

    white-space: nowrap;

}


/* =========================================
   STATUS BADGE
   ========================================= */

.cc-status {

    display: inline-flex;

    align-items: center;

    justify-content: center;

    min-height: 20px;

    padding: 3px 9px;

    box-sizing: border-box;

    border-radius: 12px;

    font-size: 9px;

    font-weight: 700;

    line-height: 1;

    text-transform: capitalize;

    white-space: nowrap;

}


/* =========================================
   REGISTERED
   ========================================= */

.status-registered {

    color: #167342;

    background: #e8f7ee;

}


/* =========================================
   CONFIRMED
   ========================================= */

.status-confirmed {

    color: #167342;

    background: #e8f7ee;

}


/* =========================================
   ATTENDED
   ========================================= */

.status-attended {

    color: #1768bd;

    background: #eaf3ff;

}


/* =========================================
   COMPLETED
   ========================================= */

.status-completed {

    color: #167342;

    background: #e8f7ee;

}


/* =========================================
   PENDING
   ========================================= */

.status-pending {

    color: #966000;

    background: #fff2d9;

}


/* =========================================
   NO SHOW
   ========================================= */

.status-no-show {

    color: #a13a32;

    background: #fdebea;

}


/* =========================================
   REJECTED
   ========================================= */

.status-rejected {

    color: #a13a32;

    background: #fdebea;

}


/* =========================================
   DETAILS CELL
   ========================================= */

.cc-details-cell {

    display: flex;

    justify-content: flex-end;

}


/* =========================================
   DETAILS BUTTON
   ========================================= */

.cc-details-btn {

    min-width: 56px;

    height: 27px;

    padding: 0 10px;

    box-sizing: border-box;

    border: 1px solid #cbd7e5;

    border-radius: 5px;

    background: #ffffff;

    color: #243650;

    font-size: 10px;

    font-weight: 600;

    line-height: 25px;

    text-align: center;

    cursor: pointer;

    transition:
        background .15s ease,
        border-color .15s ease,
        color .15s ease;

}


.cc-details-btn:hover {

    border-color: #9eb8d5;

    background: #f5f9fd;

    color: #075db8;

}


/* =========================================
   EMPTY STATE
   ========================================= */

.cc-empty {

    padding: 55px 20px;

    text-align: center;

}


.cc-empty-icon {

    width: 52px;

    height: 52px;

    display: flex;

    align-items: center;

    justify-content: center;

    margin: 0 auto 12px;

    border-radius: 13px;

    background: #eef5ff;

    font-size: 23px;

}


.cc-empty h3 {

    margin: 0 0 6px;

    color: #07152f;

    font-size: 17px;

    font-weight: 700;

}


.cc-empty p {

    margin: 0;

    color: #718096;

    font-size: 11px;

}


/* =========================================
   BOTTOM SECTION
   ========================================= */

.cc-bottom-grid {

    display: grid;

    grid-template-columns:
        2fr
        1fr;

    gap: 18px;

    margin-top: 20px;

}


/* =========================================
   PROGRESS CARD
   ========================================= */

.cc-progress-card,
.cc-qr-card {

    min-width: 0;

    padding: 22px;

    box-sizing: border-box;

    border: 1px solid #dfe6ef;

    border-radius: 10px;

    background: #ffffff;

    box-shadow:
        0 4px 16px rgba(
            7,
            21,
            47,
            .05
        );

}


.cc-progress-card h2,
.cc-qr-card h2 {

    margin: 0 0 24px;

    color: #07152f;

    font-size: 17px;

    font-weight: 700;

}


/* =========================================
   PROGRESS
   ========================================= */

.cc-progress {

    display: flex;

    align-items: flex-start;

    width: 100%;

}


.cc-progress-step {

    display: flex;

    flex-direction: column;

    align-items: center;

    min-width: 65px;

    color: #718096;

    text-align: center;

}


.cc-progress-step span {

    width: 31px;

    height: 31px;

    display: flex;

    align-items: center;

    justify-content: center;

    margin-bottom: 7px;

    box-sizing: border-box;

    border: 1px solid #d5dfeb;

    border-radius: 50%;

    background: #ffffff;

    color: #64748b;

    font-size: 11px;

    font-weight: 700;

}


.cc-progress-step label {

    color: #66758a;

    font-size: 9px;

    font-weight: 600;

    white-space: nowrap;

}


.cc-progress-step.active span {

    border-color: #0066ff;

    background: #0066ff;

    color: #ffffff;

}


.cc-progress-step.active label {

    color: #07152f;

}


.cc-progress-line {

    flex: 1;

    height: 2px;

    margin-top: 15px;

    background: #d9e1ec;

}


.cc-progress-line.active {

    background: #0066ff;

}


/* =========================================
   REGISTRATION INFORMATION
   ========================================= */

.cc-registration-info {

    display: grid;

    grid-template-columns:
        repeat(3, 1fr);

    gap: 25px;

    margin-top: 28px;

    padding-top: 20px;

    border-top: 1px solid #edf1f5;

}


.cc-registration-info label {

    display: block;

    margin-bottom: 5px;

    color: #7a8798;

    font-size: 9px;

    font-weight: 700;

    letter-spacing: .6px;

}


.cc-registration-info strong {

    display: block;

    overflow: hidden;

    color: #14213d;

    font-size: 12px;

    line-height: 1.4;

    text-overflow: ellipsis;

    white-space: nowrap;

}


/* =========================================
   QR CARD
   ========================================= */

.cc-qr-card {

    display: flex;

    flex-direction: column;

    align-items: center;

    justify-content: center;

    min-height: 240px;

    text-align: center;

}


.cc-qr-placeholder {

    width: 125px;

    height: 125px;

    display: flex;

    align-items: center;

    justify-content: center;

    margin-bottom: 17px;

    border: 5px solid #17253a;

    color: #17253a;

    font-size: 25px;

    font-weight: 800;

    letter-spacing: 3px;

}


.cc-qr-card h2 {

    margin-bottom: 7px;

}


.cc-qr-card p {

    max-width: 240px;

    margin: 0;

    color: #718096;

    font-size: 11px;

    line-height: 1.5;

}


/* =========================================
   RESPONSIVE - TABLET
   ========================================= */

@media (max-width: 1000px) {

    .cc-table-header,
    .cc-registration-row {

        grid-template-columns:
            1.7fr
            1.15fr
            1.1fr
            1fr
            .8fr
            .7fr;

    }


    .cc-my-registrations {

        padding-left: 20px;

        padding-right: 20px;

    }


    .cc-bottom-grid {

        grid-template-columns: 1fr;

    }

}


/* =========================================
   RESPONSIVE - SMALL TABLET
   ========================================= */

@media (max-width: 800px) {

    .cc-table-header,
    .cc-registration-row {

        grid-template-columns:
            1.8fr
            1.2fr
            1.15fr
            .85fr;

    }


    /* Hide registration ID */

    .cc-table-header span:nth-child(2),
    .cc-registration-row > div:nth-child(2) {

        display: none;

    }


    /* Hide event date */

    .cc-table-header span:nth-child(4),
    .cc-registration-row > div:nth-child(4) {

        display: none;

    }


    .cc-page-header h1 {

        font-size: 26px;

    }

}


/* =========================================
   RESPONSIVE - MOBILE
   ========================================= */

@media (max-width: 600px) {

    .cc-my-registrations {

        padding: 20px 12px 40px;

    }


    .cc-page-header {

        margin-bottom: 18px;

    }


    .cc-page-header h1 {

        font-size: 24px;

    }


    .cc-page-header p {

        font-size: 12px;

    }


    .cc-table-header {

        display: none;

    }


    .cc-registration-row {

        display: grid;

        grid-template-columns:
            1fr
            auto;

        gap: 8px 12px;

        min-height: auto;

        padding: 15px;

    }


    .cc-event-name {

        grid-column: 1;

        font-size: 12px;

    }


    .cc-registration-id {

        grid-column: 1;

    }


    .cc-registration-row > div:nth-child(3),
    .cc-registration-row > div:nth-child(4) {

        display: none;

    }


    .cc-registration-row > div:nth-child(5) {

        grid-column: 1;

    }


    .cc-details-cell {

        grid-column: 2;

        grid-row: 1 / span 3;

        align-items: center;

    }


    .cc-registration-info {

        grid-template-columns: 1fr;

        gap: 15px;

    }

}

sp_widget.script:
(function() {

    /*
     * =========================================
     * CAMPUS CONNECT
     * MY REGISTRATIONS
     * =========================================
     *
     * Shows registrations belonging to the
     * currently logged-in student.
     */


    data.registrations = [];

    data.loading = false;


    /*
     * =========================================
     * CURRENT USER
     * =========================================
     */

    var currentUser = gs.getUserID();


    if (!currentUser) {

        return;

    }


    /*
     * =========================================
     * GET REGISTRATIONS
     * =========================================
     */

    var registrationGR =
        new GlideRecord(
            'x_snc_campus_con_0_registrations'
        );


    /*
     * IMPORTANT:
     *
     * Only registrations of the logged-in
     * student are returned.
     */

    registrationGR.addQuery(
        'student',
        currentUser
    );


    /*
     * Show newest registrations first.
     */

    registrationGR.orderByDesc(
        'registration_date'
    );


    registrationGR.query();


    /*
     * =========================================
     * BUILD REGISTRATION DATA
     * =========================================
     */

    while (
        registrationGR.next()
    ) {

        var registration = {};


        /*
         * Registration ID
         */

        registration.sys_id =
            registrationGR.getUniqueValue();


        /*
         * Registration Status
         */

        registration.status =
            registrationGR.getDisplayValue(
                'registration_status'
            ) ||
            'Registered';


        registration.statusValue =
            (
                registrationGR.getValue(
                    'registration_status'
                ) ||
                ''
            ).toLowerCase();


        /*
         * Registration Date
         */

        registration.registrationDate =
            registrationGR.getDisplayValue(
                'registration_date'
            );


        /*
         * =========================================
         * EVENT INFORMATION
         * =========================================
         *
         * Registration.Event is a reference
         * to the Events table.
         */

        registration.eventName =
            registrationGR.getDisplayValue(
                'event'
            ) ||
            'Event';


        registration.eventDate =
            'Date not available';


        registration.location =
            'Location not specified';


        registration.eventType =
            'Campus Event';


        registration.technologyTags =
            '';


        /*
         * =========================================
         * LOAD EVENT RECORD
         * =========================================
         */

        var eventId =
            registrationGR.getValue(
                'event'
            );


        if (eventId) {

            var eventGR =
                new GlideRecord(
                    'x_snc_campus_con_0_events'
                );


            if (
                eventGR.get(eventId)
            ) {

                /*
                 * Event Name
                 */

                registration.eventName =
                    eventGR.getDisplayValue(
                        'event_name'
                    );


                /*
                 * Event Date
                 */

                registration.eventDate =
                    eventGR.getDisplayValue(
                        'event_date'
                    );


                /*
                 * Location
                 */

                registration.location =
                    eventGR.getDisplayValue(
                        'location'
                    ) ||
                    'Location not specified';


                /*
                 * Event Type
                 */

                registration.eventType =
                    eventGR.getDisplayValue(
                        'event_type'
                    ) ||
                    'Campus Event';


                /*
                 * Technology Tags
                 */

                registration.technologyTags =
                    eventGR.getValue(
                        'technology_tags'
                    ) ||
                    '';

            }

        }


        /*
         * =========================================
         * TECHNOLOGY TAG ARRAY
         * =========================================
         */

        registration.technologyTagsArray = [];


        if (
            registration.technologyTags
        ) {

            registration.technologyTagsArray =
                registration.technologyTags
                    .split(/[,;\n]/)
                    .map(function(tag) {

                        return tag.trim();

                    })
                    .filter(function(tag) {

                        return tag.length > 0;

                    });

        }


        /*
         * =========================================
         * ADD TO RESULT
         * =========================================
         */

        data.registrations.push(
            registration
        );

    }


})();
